/* ---------- 0. UTILIDADES ---------- */
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const ROOT=document.body.dataset.root||''; // '' en Inicio, '../' en las páginas dentro de carpetas
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc=s=>String(s).replace(/"/g,'&quot;');
const alt=p=>ALT[p]||"Imagen de D'Salms";
/* Botón-miniatura que abre el lightbox */
const ph=(p,a,x='',rv=false)=>{const[w,h]=DIM[p]||[4,3];return `<button ${x} class="ph${rv?' rv':''}" data-lb type="button" aria-label="Ampliar: ${esc(a)}"><img src="${ROOT}img/${p}" alt="${esc(a)}" width="${w}" height="${h}" loading="lazy"></button>`};

/* ---------- 1. CARRUSEL (arrastrar, flechas, teclado, autoplay, barra de progreso) ---------- */
function makeCar(el,items,h){
  if(el._off)el._off();
  el.style.setProperty('--h',(h||el.dataset.h||340)+'px');
  el.innerHTML=`<div class="car-in"><div class="car-track" tabindex="0" role="region" aria-label="Carrusel de imágenes (usa las flechas del teclado)">${items.map(([p,a])=>ph(p,a)).join('')}</div>
  <div class="car-ui"><button type="button" class="car-b" data-d="-1" aria-label="Anterior">←</button><span class="car-c"></span><i class="car-bar"><b></b></i><button type="button" class="car-b" data-d="1" aria-label="Siguiente">→</button></div></div>`;
  const box=$('.car-in',el),tr=$('.car-track',el),sl=$$('.ph',tr),bar=$('.car-bar b',el),cnt=$('.car-c',el);
  let idx=0,hover=false,vis=false,drag=false,moved=false,raf;
  const mid=s=>s.offsetLeft+s.offsetWidth/2;
  const pad=()=>{if(!sl.length||!sl[0].offsetWidth)return;tr.style.paddingInline=Math.max(0,(tr.clientWidth-sl[0].offsetWidth)/2)+'px'};
  const upd=()=>{const m=tr.scrollLeft+tr.clientWidth/2;let b=0,bd=1e9;sl.forEach((s,i)=>{const d=Math.abs(mid(s)-m);if(d<bd){bd=d;b=i}});idx=b;
    sl.forEach((s,i)=>s.classList.toggle('on',i===b));cnt.textContent=`${b+1} / ${sl.length}`;bar.style.width=((b+1)/sl.length*100)+'%'};
  const go=i=>{i=(i+sl.length)%sl.length;tr.scrollTo({left:mid(sl[i])-tr.clientWidth/2,behavior:reduce?'auto':'smooth'})};
  tr.addEventListener('scroll',()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(upd)},{passive:true});
  const ro=new ResizeObserver(()=>{pad();upd()});ro.observe(tr);
  $('.car-ui',el).addEventListener('click',e=>{const b=e.target.closest('.car-b');if(b)go(idx+ +b.dataset.d)});
  tr.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();go(idx+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(idx-1)}});
  /* arrastrar con el mouse (en móvil funciona el deslizar nativo) */
  tr.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button)return;const x0=e.clientX,s0=tr.scrollLeft;drag=true;moved=false;tr.classList.add('drag');
    const mv=ev=>{const d=ev.clientX-x0;if(Math.abs(d)>6)moved=true;tr.scrollLeft=s0-d};
    const up=()=>{removeEventListener('pointermove',mv);removeEventListener('pointerup',up);drag=false;tr.classList.remove('drag');upd();go(idx)};
    addEventListener('pointermove',mv);addEventListener('pointerup',up)});
  tr.addEventListener('click',e=>{if(moved){e.stopPropagation();e.preventDefault();moved=false}},true);
  box.addEventListener('pointerenter',()=>hover=true);box.addEventListener('pointerleave',()=>hover=false);
  box.addEventListener('focusin',()=>hover=true);box.addEventListener('focusout',()=>hover=false);
  const io=new IntersectionObserver(e=>vis=e[0].isIntersecting,{threshold:.35});io.observe(el);
  const t=reduce?0:setInterval(()=>{if(vis&&!hover&&!drag&&$('.lb').hidden&&!document.hidden)go(idx+1)},3600+Math.random()*1400);
  el._off=()=>{clearInterval(t);ro.disconnect();io.disconnect()};
  pad();upd();
}
$$('[data-car]').forEach(el=>makeCar(el,(GAL[el.dataset.car]||[]).map(([p,a])=>[p,a])));

/* ---------- 2. APLICACIONES: un carrusel por grupo + mosaico ---------- */
