$('#tonos').innerHTML=tabs(TONOS.map(t=>t[0]),'Tonos de comunicación')+TONOS.map((t,i)=>`<div role="tabpanel" class="vpanel"><div class="vl"><span class="vn">0${i+1}</span><h4>${t[0]}</h4><p class="pq"><small>Queremos que digan</small>“${t[1]}”</p><p class="lab">Cómo lo lograremos</p><ul class="how">${t[3].map(x=>`<li>${x}</li>`).join('')}</ul></div>
<div><p class="lab">5 frases de ejemplo</p>${bubbles(t[2])}</div><div class="car" data-t="${i}"></div></div>`).join('');
$$('[data-t]').forEach(el=>makeCar(el,TONOS[el.dataset.t][4].map(p=>[p,alt(p)]),260));
