const hv=$('#heroVid'),vb=$('#vid');
const chk=()=>{if(hv.networkState===3||hv.error)vb.classList.add('no-video')};
hv.addEventListener('error',chk,true);$('source',hv).addEventListener('error',chk);hv.addEventListener('loadeddata',()=>vb.classList.remove('no-video'));setTimeout(chk,1200);
