const TY=[['Títulos','Kalnia','600–700','clamp(2rem, 5vw, 3.6rem)','Nombre de marca, titulares y frases destacadas','Display serif de alto contraste: elegante, con presencia. No para textos largos ni tamaños pequeños.',"var(--font-title)",'Viste tu esencia'],['Subtítulos','DM Sans (peso medio)','500','1.1–1.5 rem','Bajadas de título y categorías','Geométrica, cálida y legible.',"var(--font-body)",'Moda cristiana contemporánea'],['Cuerpo','DM Sans (regular)','400','1–1.1 rem','Descripciones, textos de redes y datos comerciales','Neutra y clara: deja que Kalnia sea la protagonista.',"var(--font-body)",'Diseños con mensaje, hechos para acompañarte cada día.'],['CTA','DM Sans (negrita)','700','0.9–1 rem','Botones y llamados a la acción','Directa y fácil de tocar.',"var(--font-body)",'Escríbenos']];
if($('#typer')){ /* solo en las páginas que tienen este componente */
$('#typer').innerHTML=`<div role="tablist" aria-label="Nivel tipográfico">${TY.map(t=>`<button role="tab" type="button">${t[0]}</button>`).join('')}</div><div class="ty-card"><p class="ty-s" id="tyS"></p><dl id="tyD"></dl><label>Tamaño <input type="range" id="tyR" min="14" max="72" value="40"></label></div>`;
const tt=$$('#typer [role=tab]'),setTy=i=>{const t=TY[i];tt.forEach((b,k)=>b.setAttribute('aria-selected',k==i));const s=$('#tyS');s.textContent=t[7];s.style.fontFamily=t[6];s.style.fontWeight=t[0]==='CTA'?700:t[0]==='Subtítulos'?500:t[0]==='Títulos'?600:400;$('#tyD').innerHTML=`<div><dt>Fuente</dt><dd>${t[1]}</dd></div><div><dt>Peso (propuesta)</dt><dd>${t[2]}</dd></div><div><dt>Tamaño sugerido (propuesta)</dt><dd>${t[3]}</dd></div><div><dt>Uso (documento)</dt><dd>${t[4]}</dd></div><div><dt>Personalidad</dt><dd>${t[5]}</dd></div>`};
tt.forEach((b,i)=>b.onclick=()=>setTy(i));$('#tyR').oninput=e=>$('#tyS').style.fontSize=e.target.value+'px';$('#tyS').style.fontSize='40px';setTy(0);
}
/* Dimensiones de la imagen: órbita interactiva */
const DIMS=[['Comercial','Comercial / producto',['Calidad','Precio','Valor','Productos','Servicios'],'Lo que el cliente percibe de las prendas: se ven bien hechas y valen lo que cuestan.'],['Financiera','Financiera',['Solidez','Rentabilidad','Fiabilidad'],'Confianza en que la marca es estable y cumple.'],['Social','Social / ciudadana',['Comunidad','Medio ambiente','Responsabilidad social'],'Cómo se relaciona la marca con su comunidad.'],['Interna','Interna / laboral',['Clima','Pertenencia','Empleados','Talento'],'Orgullo de quienes hacen la marca.'],['Institucional','Institucional / corporativa',['Historia','Valores','Ética','Comportamiento','Percepción'],'Lo que la marca es y cómo se comporta.']];
if($('#orbit')){ /* solo en las páginas que tienen este componente */
const pos=i=>{const a=(i*72-90)*Math.PI/180;return[50+39*Math.cos(a),50+39*Math.sin(a)]};
$('#orbit').innerHTML=`<svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="39" class="o-ring"/>${DIMS.map((d,i)=>{const[x,y]=pos(i);return `<line x1="50" y1="50" x2="${x}" y2="${y}"/>`}).join('')}</svg><img class="o-c" src="${ROOT}img/logo.png" alt="D'Salms" width="120" height="118">`+DIMS.map((d,i)=>{const[x,y]=pos(i);return `<button type="button" class="o-n" style="left:${x}%;top:${y}%" data-o="${i}" aria-pressed="false">${d[0]}</button>`}).join('');
const setO=i=>{$$('.o-n').forEach((b,k)=>{b.classList.toggle('on',k==i);b.setAttribute('aria-pressed',k==i)});const d=DIMS[i];$('#orbitInfo').innerHTML=`<h4>${d[1]}</h4><p>${d[3]}</p><ul class="chips">${d[2].map(x=>`<li>${x}</li>`).join('')}</ul><small>Marco conceptual: el documento no desarrolla estos puntos para D'Salms.</small>`};
$('#orbit').addEventListener('click',e=>{const b=e.target.closest('[data-o]');if(b)setO(+b.dataset.o)});setO(0);
}
