/* Plan de fortalecimiento */
const PLAN=[['Estandarización','Área de seguridad, tamaño mínimo y usos incorrectos del logo sin definir.','El símbolo D + S ya funciona como silueta compacta.','Elaborar un manual con versiones, medidas y usos incorrectos.','Logo consistente en prendas, bordado y pantalla.'],['Material publicitario','Faltan fotografías reales y piezas de packaging.','Ya existen mockups y una línea visual definida.','Producir packaging, etiquetas, letrero y tableros de dirección de arte por colección.','Una marca más profesional y reconocible.'],['Colores y tipografías','Kalnia no funciona en textos largos ni tamaños pequeños.','La pareja Kalnia + DM Sans ya está propuesta.','Fijar la jerarquía y probarla en soportes reales.','Lectura clara y estilo uniforme.'],['Redes sociales','Los perfiles aún están por definir.','Instagram, Facebook, TikTok y WhatsApp Business pueden compartir una identidad.','Crear plantillas para posts, historias, portadas y campañas.','Presencia reconocible a simple vista.'],['Comunicación','El tono todavía no tiene una guía con ejemplos.','La personalidad cercana y juvenil ya está definida.','Una guía breve de voz con frases tipo y palabras a evitar.','Mensajes coherentes en todos los canales.'],['Aplicaciones digitales','El sitio web y el catálogo digital aún no existen.','Esta web puede ser la base.','Evolucionarla hacia la web oficial con catálogo y pedido por WhatsApp.','Pedidos más fáciles y marca presente en línea.']];
if($('#plan'))$('#plan').innerHTML=tabs(PLAN.map(p=>p[0]),'Plan de fortalecimiento')+PLAN.map(p=>`<div role="tabpanel" class="vpanel plan">${['Problema','Oportunidad','Propuesta','Beneficio'].map((l,k)=>`<div class="pl" style="--i:${k}"><small>${l}</small>${p[k+1]}</div>`).join('')}</div>`).join('');

/* ---------- 4. PESTAÑAS (accesibles) ---------- */
$$('[data-tabs]').forEach(t=>{const tb=$$(':scope>[role=tablist]>[role=tab]',t),pn=$$(':scope>[role=tabpanel]',t);
  const go=i=>{tb.forEach((b,j)=>{b.setAttribute('aria-selected',j==i);b.tabIndex=j==i?0:-1});pn.forEach((p,j)=>p.hidden=j!=i)};
  tb.forEach((b,i)=>{b.addEventListener('click',()=>go(i));b.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const n=(i+(e.key==='ArrowRight'?1:-1)+tb.length)%tb.length;go(n);tb[n].focus()}})});go(0)});

/* ---------- 8. MENÚ + SECCIÓN ACTIVA + VOLVER ARRIBA ---------- */
const burger=$('.burger'),menu=$('#menu'),links=$$('a',menu);
const closeMenu=()=>{menu.classList.remove('open');burger.setAttribute('aria-expanded','false')};
burger.addEventListener('click',()=>{const o=menu.classList.toggle('open');burger.setAttribute('aria-expanded',o)});
links.forEach(a=>a.addEventListener('click',closeMenu));
// const spy=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+e.target.id))}),{rootMargin:'-45% 0px -50% 0px'});
// $$('main section[id]').forEach(s=>spy.observe(s));
const up=$('button.up');up.onclick=()=>scrollTo({top:0});
/* ---------- 8b. PLAN: índice fijo que marca el apartado visible ---------- */
if($('.plan-bar')){const pl=$$('.plan-bar a'),bx=$('.plan-bar');
const pio=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;pl.forEach(a=>{const on=a.getAttribute('href')==='#'+e.target.id;a.classList.toggle('on',on);if(on){a.setAttribute('aria-current','true');bx.scrollTo({left:a.offsetLeft-bx.clientWidth/2+a.offsetWidth/2,behavior:reduce?'auto':'smooth'})}else a.removeAttribute('aria-current')})}),{rootMargin:'-30% 0px -60% 0px'});
$$('.pt').forEach(s=>pio.observe(s))}

/* ---------- 9. ANIMACIÓN AL HACER SCROLL (IntersectionObserver + stagger) ---------- */
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.12});
$$('.rv').forEach(el=>{const sib=[...el.parentElement.children].filter(c=>c.classList.contains('rv'));el.style.setProperty('--d',Math.min(sib.indexOf(el),5)*100+'ms');io.observe(el)});
const pars=$$('[data-par]');
addEventListener('scroll',()=>{up.hidden=scrollY<700;if(!reduce&&scrollY<1200)pars.forEach(p=>p.style.transform=`translateY(${scrollY*p.dataset.par}px)`)},{passive:true});

/* ---------- 10. COPIAR HEX ---------- */
$$('.sw').forEach(b=>b.addEventListener('click',()=>{const h=b.dataset.hex;navigator.clipboard&&navigator.clipboard.writeText(h).catch(()=>{});$('#copied').textContent='Copiado '+h+' · ficha abajo'}));

/* ---------- 11. LIGHTBOX ---------- */
const lb=$('.lb'),lbi=$('img',lb),cap=$('figcaption',lb),cnt=$('.lb-c',lb);let list=[],cur=0,opener=null;
const src=el=>el.tagName==='IMG'?el:$('img',el);
const collect=()=>$$('[data-lb]').filter(e=>!e.closest('[hidden]')&&!e.dataset.clone);
const show=i=>{cur=(i+list.length)%list.length;const im=src(list[cur]);lbi.src=im.currentSrc||im.src;lbi.alt=im.alt;cap.textContent=im.alt;cnt.textContent=`${cur+1} / ${list.length}`};
const open=el=>{if(el.dataset.clone)el=$(`[data-mq="${el.dataset.mq}"]:not([data-clone])`);list=collect();opener=el;show(Math.max(0,list.indexOf(el)));lb.hidden=false;document.body.style.overflow='hidden';$('.lb-x').focus()};
const close=()=>{lb.hidden=true;document.body.style.overflow='';opener&&opener.focus&&opener.focus()};
document.addEventListener('click',e=>{const t=e.target.closest('[data-lb]');if(t)open(t)});
$$('img[data-lb]').forEach(i=>{i.tabIndex=0;i.setAttribute('role','button');i.addEventListener('keydown',e=>{if(e.key==='Enter')open(i)})});
$('.lb-x').onclick=close;$('.lb-p').onclick=()=>show(cur-1);$('.lb-n').onclick=()=>show(cur+1);
lb.addEventListener('click',e=>{if(e.target===lb||e.target.tagName==='FIGURE')close()});
document.addEventListener('keydown',e=>{if(lb.hidden)return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(cur-1);if(e.key==='ArrowRight')show(cur+1);
  if(e.key==='Tab'){const f=$$('button',lb);const a=document.activeElement;if(e.shiftKey&&a===f[0]){e.preventDefault();f[f.length-1].focus()}else if(!e.shiftKey&&a===f[f.length-1]){e.preventDefault();f[0].focus()}}});
let sx=0;lb.addEventListener('touchstart',e=>sx=e.changedTouches[0].clientX,{passive:true});
lb.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-sx;if(Math.abs(d)>50)show(cur+(d<0?1:-1))},{passive:true});
